def distances_to_zero(arr):
    n = len(arr)
    result = [float('inf')] * n
    last_zero_index = None

    # Traverse left to right to find distances to the nearest zero on the left
    for i in range(n):
        if arr[i] == 0:
            last_zero_index = i
        elif last_zero_index is not None:
            result[i] = i - last_zero_index

    # Traverse right to left to find distances to the nearest zero on the right
    last_zero_index = None
    for i in range(n-1, -1, -1):
        if arr[i] == 0:
            last_zero_index = i
        elif last_zero_index is not None:
            dist = last_zero_index - i
            if dist < result[i]:
                result[i] = dist

    return result

